#!/bin/sh
# CB-LAB-SYS-001 - Every Linux engine
# Generated by CIRSEC Baselines tools/generate.py from lab 0.1.0, profile strict. Do not edit.
# SPDX-License-Identifier: Apache-2.0
#
# Usage: CB-LAB-SYS-001.sh check | fix [--apply]
# Exit codes of check: 0 pass, 1 fail, 2 not applicable, 3 error, 4 manual or review.
set -u

# <tools/lib/cirsec.sh>

CB_CONTROL=CB-LAB-SYS-001
CB_LOGIC=all
CB_ASSESSMENT=partial
CB_MAX_AUTH=4; export CB_MAX_AUTH

cb_detect_has_tmp() {
(
test -d /tmp
)
}

cb_applicable() {
  cb_version_in a || return $?
  cb_fact has_tmp || return $?
  return 0
}

cb_check_forward() {
  o=$(sysctl -n net.ipv4.ip_forward 2>/dev/null | tr -s '\t ' '  ') || return 3
  printf '%s\n' "$o"
  cb_cmp "$o" == 0
}

cb_check_auth_tries() {
  o=$(cb_sshd -T 2>/dev/null | awk -v k=maxauthtries '$1 == k { $1 = ""; sub(/^ /, ""); print; exit }')
  [ -n "$o" ] || return 3
  printf '%s\n' "$o"
  cb_cmp "$o" '<=' 4
}

cb_check_telnet() {
  case $(dpkg-query -W -f='${Status}' telnetd 2>/dev/null) in
    *' installed') o=installed ;;
    *) o=absent ;;
  esac
  printf '%s\n' "$o"
  [ "$o" = absent ]
}

cb_check_avahi() {
  o=$(systemctl is-enabled avahi-daemon.service 2>/dev/null)
  [ -n "$o" ] || o=not-found
  printf '%s\n' "$o"
  case $o in masked | not-found) return 0 ;; esac
  return 1
}

cb_check_shadow() {
  rc=0 found=0
  for f in /etc/gshadow*; do
    [ -e "$f" ] || continue
    found=1
    # shellcheck disable=SC2046
    set -- $(stat -c '%U %G %a' "$f")
    printf '%s %s:%s %s\n' "$f" "$1" "$2" "$3"
    [ "$1" = root ] || rc=1
    [ "$2" = shadow ] || rc=1
    [ $((0$3 & ~0640)) -eq 0 ] || rc=1
  done
  [ "$found" = 1 ] || return 2
  return "$rc"
}

cb_check_lock() {
  o=$(dconf read /org/gnome/desktop/screensaver/lock-enabled 2>/dev/null)
  printf '%s\n' "$o"
  [ "$o" = true ] || return 1
  grep -rqsx -- /org/gnome/desktop/screensaver/lock-enabled /etc/dconf/db/local.d/locks/ || { echo 'not locked'; return 1; }
}

cb_check_no_nopasswd() {
  found=0 hit=0
  for f in /etc/sudoers.d/*; do
    [ -f "$f" ] || continue
    found=1
    if grep -Eq -- NOPASSWD "$f"; then
      hit=1
      grep -EHm 3 -- NOPASSWD "$f"
    fi
  done
  [ "$found" = 1 ] || return 2
  [ "$hit" = 0 ]
}

cb_check_no_suid_tmp() {
  command -v osqueryi >/dev/null 2>&1 || return 3
  o=$(osqueryi --csv --header=false 'SELECT path FROM suid_bin WHERE path LIKE '"'"'/tmp/%'"'"'' 2>/dev/null) || return 3
  printf '%s\n' "$o" | head -n 5
  [ -z "$o" ]
}

cb_run_checks() {
  cb_try forward '' '' cb_check_forward '== 0'
  cb_try auth-tries '' '' cb_check_auth_tries '<= 4'
  cb_try telnet '' '' cb_check_telnet absent
  cb_try avahi '' '' cb_check_avahi masked
  cb_try shadow '' '' cb_check_shadow 'owner root, group shadow, mode <= 0640'
  cb_try lock '' has_tmp cb_check_lock '== true'
  cb_try no-nopasswd '' '' cb_check_no_nopasswd 'no_match NOPASSWD'
  cb_try no-suid-tmp '' '' cb_check_no_suid_tmp no_rows
}

cb_fix_forward() {
  f=/etc/sysctl.d/60-cirsec.conf
  cb_backup "$f"
  touch "$f"
  sed -i '/^[[:space:]]*net\.ipv4\.ip_forward[[:space:]]*=/d' "$f"
  printf '%s = %s\n' net.ipv4.ip_forward 0 >>"$f"
  sysctl -q -w net.ipv4.ip_forward=0
}

cb_fix_auth_tries() {
  grep -Eqi '^[[:space:]]*Include[[:space:]]+/etc/ssh/sshd_config.d/\*\.conf' /etc/ssh/sshd_config || {
    echo '/etc/ssh/sshd_config does not include sshd_config.d/*.conf' >&2
    return 1
  }
  f=/etc/ssh/sshd_config.d/00-cirsec.conf
  mkdir -p /etc/ssh/sshd_config.d
  cb_backup "$f"
  touch "$f"
  sed -i '/^[[:space:]]*maxauthtries[[:space:]]/Id' "$f"
  printf '%s %s\n' maxauthtries 4 >>"$f"
  if ! cb_sshd -t; then
    cb_restore "$f"
    echo 'sshd -t rejected the change, reverted' >&2
    return 1
  fi
}

cb_fix_telnet() {
  DEBIAN_FRONTEND=noninteractive apt-get -o DPkg::Lock::Timeout=300 purge -y -q telnetd
}

cb_fix_avahi() {
  systemctl mask --now avahi-daemon.service
}

cb_fix_shadow() {
  for f in /etc/gshadow*; do
    [ -e "$f" ] || continue
    # shellcheck disable=SC2046
    set -- $(stat -c '%U %G %a' "$f")
    [ "$1" = root ] || chown root "$f" || return 1
    [ "$2" = shadow ] || chgrp shadow "$f" || return 1
    [ $((0$3 & ~0640)) -eq 0 ] || chmod "$(printf '%o' $((0$3 & 0640)))" "$f" || return 1
  done
}

cb_fix_lock() {
  mkdir -p /etc/dconf/db/local.d/locks /etc/dconf/profile
  [ -f /etc/dconf/profile/user ] || printf 'user-db:user\nsystem-db:local\n' >/etc/dconf/profile/user
  grep -qx 'system-db:local' /etc/dconf/profile/user || {
    echo '/etc/dconf/profile/user does not use system-db:local' >&2
    return 1
  }
  f=/etc/dconf/db/local.d/00-cirsec-org-gnome-desktop-screensaver-lock-enabled
  cb_backup "$f"
  printf '[%s]\n%s=%s\n' org/gnome/desktop/screensaver lock-enabled true >"$f"
  l=/etc/dconf/db/local.d/locks/00-cirsec-org-gnome-desktop-screensaver-lock-enabled
  cb_backup "$l"
  printf '%s\n' /org/gnome/desktop/screensaver/lock-enabled >"$l"
  dconf update
}

cb_run_fixes() {
  cb_fixit forward '' '' cb_check_forward cb_fix_forward
  cb_fixit auth-tries '' '' cb_check_auth_tries cb_fix_auth_tries
  cb_fixit telnet '' '' cb_check_telnet cb_fix_telnet
  cb_fixit avahi '' '' cb_check_avahi cb_fix_avahi
  cb_fixit shadow '' '' cb_check_shadow cb_fix_shadow
  cb_fixit lock '' has_tmp cb_check_lock cb_fix_lock
}

cb_main "$@"
